  `bank` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_status` enum('pending','settlement','expire','cancel','deny') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
